import re
from decimal import Decimal

class InsufficientFunds(Exception):
    pass

_AMOUNT_RE = re.compile(r'[0-9]+(?:\.[0-9]{1,2})?')

class Ledger:
    def __init__(self, overdraft_limit='0.00'):
        self._limit = self._parse_limit(overdraft_limit)
        self._balance = Decimal('0')
        self._history = []

    @staticmethod
    def _parse_limit(value):
        if not isinstance(value, str):
            raise TypeError("overdraft_limit must be a string")
        if not _AMOUNT_RE.fullmatch(value):
            raise ValueError("invalid overdraft_limit format")
        return Decimal(value)

    @staticmethod
    def _parse_amount(value):
        if not isinstance(value, str):
            raise TypeError("amount must be a string")
        if not _AMOUNT_RE.fullmatch(value):
            raise ValueError("invalid amount format")
        d = Decimal(value)
        if d == 0:
            raise ValueError("amount must not be zero")
        return d

    @staticmethod
    def _fmt(value):
        value = value.quantize(Decimal('0.01'))
        if value == 0:
            return '0.00'
        return format(value, '.2f')

    def deposit(self, amount):
        d = self._parse_amount(amount)
        self._balance += d
        self._history.append(('deposit', self._fmt(d)))

    def withdraw(self, amount):
        d = self._parse_amount(amount)
        new_balance = self._balance - d
        if new_balance < -self._limit:
            raise InsufficientFunds()
        self._balance = new_balance
        self._history.append(('withdraw', self._fmt(d)))
        if self._balance < 0:
            self._balance -= Decimal('1.50')
            self._history.append(('fee', '1.50'))

    def balance(self):
        return self._fmt(self._balance)

    def history(self):
        return list(self._history)
