import heapq


class CycleError(ValueError):
    def __init__(self, nodes, message=None):
        self.nodes = sorted(nodes)
        if message is None:
            message = f"cycle detected; unplaceable nodes: {self.nodes}"
        super().__init__(message)


def topo_order(nodes, edges):
    node_set = set(nodes)
    adj = {n: [] for n in node_set}
    indeg = {n: 0 for n in node_set}
    seen_edges = set()

    for before, after in edges:
        if before not in node_set:
            raise ValueError(f"unknown node: {before!r}")
        if after not in node_set:
            raise ValueError(f"unknown node: {after!r}")
        if (before, after) in seen_edges:
            continue
        seen_edges.add((before, after))
        adj[before].append(after)
        indeg[after] += 1

    heap = [n for n, d in indeg.items() if d == 0]
    heapq.heapify(heap)

    order = []
    remaining_indeg = indeg.copy()

    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for succ in adj[n]:
            remaining_indeg[succ] -= 1
            if remaining_indeg[succ] == 0:
                heapq.heappush(heap, succ)

    if len(order) != len(node_set):
        unplaceable = {n for n, d in remaining_indeg.items() if d > 0}
        raise CycleError(unplaceable)

    return order


def layers(nodes, edges):
    order = topo_order(nodes, edges)
    node_set = set(order)
    pred = {n: set() for n in node_set}

    for before, after in edges:
        pred[after].add(before)

    layer_of = {}
    for n in order:
        if not pred[n]:
            layer_of[n] = 0
        else:
            layer_of[n] = 1 + max(layer_of[p] for p in pred[n])

    if not layer_of:
        return []

    result = [[] for _ in range(max(layer_of.values()) + 1)]
    for n, lvl in layer_of.items():
        result[lvl].append(n)

    for lvl in result:
        lvl.sort()

    return result
