"""Half-open interval utilities."""

__all__ = ["merge", "subtract", "total_length"]


def _normalize(intervals):
    normalized = []
    for interval in intervals:
        if len(interval) != 2:
            raise ValueError("Each interval must be a 2-item sequence")
        start, end = interval
        if start > end:
            raise ValueError(f"Invalid interval: start ({start}) > end ({end})")
        if start == end:
            continue
        normalized.append((start, end))
    return normalized


def merge(intervals):
    """Return a sorted, merged list of disjoint half-open intervals as tuples."""
    normalized = _normalize(intervals)
    normalized.sort(key=lambda iv: iv[0])

    merged = []
    for start, end in normalized:
        if not merged:
            merged.append((start, end))
            continue
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged


def subtract(a, b):
    """Return the points in a that are not in b, as merged sorted tuples."""
    a_merged = merge(a)
    b_merged = merge(b)

    result = []
    j = 0
    b_len = len(b_merged)

    for start, end in a_merged:
        while j < b_len and b_merged[j][1] <= start:
            j += 1

        current = start
        while j < b_len and b_merged[j][0] < end:
            b_start, b_end = b_merged[j]
            if b_start > current:
                result.append((current, b_start))
            current = max(current, b_end)
            if current >= end:
                break
            if b_end < end:
                j += 1
            else:
                break

        if current < end:
            result.append((current, end))

    return result


def total_length(intervals):
    """Return the total length covered by the union of the intervals."""
    return sum(end - start for start, end in merge(intervals))
