def _is_digits(s: str) -> bool:
    return bool(s) and all("0" <= c <= "9" for c in s)


def expand_field(field: str, lo: int, hi: int) -> list[int]:
    if not field:
        raise ValueError("invalid cron: empty field")

    values = set()
    for item in field.split(","):
        if not item:
            raise ValueError("invalid cron: empty item")

        base, sep, step_str = item.partition("/")
        step = 1
        if sep:
            if not _is_digits(step_str):
                raise ValueError("invalid cron: step must be a positive integer")
            step = int(step_str)
            if step < 1:
                raise ValueError("invalid cron: step must be >= 1")

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            a_str, _, b_str = base.partition("-")
            if not _is_digits(a_str) or not _is_digits(b_str):
                raise ValueError("invalid cron: range bounds must be integers")
            a = int(a_str)
            b = int(b_str)
            if a < lo or b > hi or a > b:
                raise ValueError("invalid cron: range out of order or out of bounds")
            start, end = a, b
        else:
            if not _is_digits(base):
                raise ValueError("invalid cron: value must be an integer")
            n = int(base)
            if n < lo or n > hi:
                raise ValueError("invalid cron: value out of bounds")
            if step == 1:
                values.add(n)
                continue
            start, end = n, hi

        values.update(range(start, end + 1, step))

    return sorted(values)


def _parse_expr(expr: str):
    parts = expr.strip().split()
    if len(parts) != 2:
        raise ValueError("invalid cron: expression must contain exactly two fields")
    minute_field, hour_field = parts
    return expand_field(minute_field, 0, 59), expand_field(hour_field, 0, 23)


def cron_matches(expr: str, hour: int, minute: int) -> bool:
    minutes, hours = _parse_expr(expr)
    return minute in minutes and hour in hours


def next_match(expr: str, hour: int, minute: int) -> tuple[int, int]:
    minutes, hours = _parse_expr(expr)
    minute_set = set(minutes)
    hour_set = set(hours)

    start = hour * 60 + minute
    for t in range(start + 1, 24 * 60):
        h = t // 60
        m = t % 60
        if h in hour_set and m in minute_set:
            return h, m

    return min(hour_set), min(minute_set)
