class Scheduler:
    def __init__(self):
        self._tasks = {}
        self._insertion_counter = 0
        self._completed_count = 0

    def add(self, name, priority, after=()):
        if name in self._tasks:
            raise ValueError(name)
        deps = tuple(after)
        for dep in deps:
            if dep not in self._tasks:
                raise KeyError(dep)
        self._tasks[name] = [priority, deps, self._insertion_counter, "pending"]
        self._insertion_counter += 1

    def next(self):
        best_name = None
        best_priority = None
        best_index = None
        for name, (priority, deps, index, state) in self._tasks.items():
            if state != "pending":
                continue
            ready = True
            for dep in deps:
                if self._tasks[dep][3] != "completed":
                    ready = False
                    break
            if not ready:
                continue
            if (
                best_name is None
                or priority > best_priority
                or (priority == best_priority and index < best_index)
            ):
                best_name = name
                best_priority = priority
                best_index = index
        if best_name is None:
            return None
        self._tasks[best_name][3] = "running"
        return best_name

    def complete(self, name):
        if name not in self._tasks:
            raise KeyError(name)
        if self._tasks[name][3] != "running":
            raise ValueError(name)
        self._tasks[name][3] = "completed"
        self._completed_count += 1

    def remaining(self):
        return len(self._tasks) - self._completed_count
