def parse_csv_line(line, delimiter=',', quote='"'):
    if len(delimiter) != 1 or len(quote) != 1:
        raise ValueError("delimiter and quote must be single characters")
    if delimiter == quote:
        raise ValueError("delimiter and quote must be different")

    result = []
    i = 0
    n = len(line)

    while True:
        if i >= n:
            result.append('')
            break

        if line[i] == quote:
            i += 1
            buf = []
            closed = False
            while i < n:
                if line[i] == quote:
                    if i + 1 < n and line[i + 1] == quote:
                        buf.append(quote)
                        i += 2
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    buf.append(line[i])
                    i += 1
            if not closed:
                raise ValueError("unclosed quoted field")
            if i < n and line[i] != delimiter:
                raise ValueError("closing quote not followed by delimiter or end of line")
            result.append(''.join(buf))
        else:
            j = line.find(delimiter, i)
            if j == -1:
                result.append(line[i:])
                i = n
            else:
                result.append(line[i:j])
                i = j

        if i < n and line[i] == delimiter:
            i += 1
            continue
        break

    return result


def format_csv_line(fields, delimiter=',', quote='"'):
    if len(delimiter) != 1 or len(quote) != 1:
        raise ValueError("delimiter and quote must be single characters")
    if delimiter == quote:
        raise ValueError("delimiter and quote must be different")

    out = []
    for field in fields:
        if (delimiter in field or quote in field or '\n' in field or '\r' in field
                or field.startswith(' ') or field.endswith(' ')):
            escaped = field.replace(quote, quote + quote)
            out.append(quote + escaped + quote)
        else:
            out.append(field)
    return delimiter.join(out)
