import re

def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)

def allocate(total_cents, ratios):
    if not _is_int(total_cents):
        raise ValueError("total_cents must be a non-negative integer")
    if total_cents < 0:
        raise ValueError("total_cents must be non-negative")
    if not isinstance(ratios, list):
        raise ValueError("ratios must be a list")
    if len(ratios) == 0:
        raise ValueError("ratios must not be empty")

    for r in ratios:
        if not _is_int(r):
            raise ValueError("ratios must be non-negative integers")
        if r < 0:
            raise ValueError("ratios must be non-negative")

    total_ratio = sum(ratios)
    if total_ratio == 0:
        raise ValueError("sum of ratios must not be zero")

    n = len(ratios)
    result = [total_cents * r // total_ratio for r in ratios]
    remainders = [(total_cents * r) % total_ratio for r in ratios]
    leftover = total_cents - sum(result)

    order = sorted(
        range(n),
        key=lambda i: (-remainders[i], -ratios[i], i),
    )

    for idx in order[:leftover]:
        result[idx] += 1

    return result

def allocate_amount(amount, ratios):
    if not isinstance(amount, str):
        raise ValueError("amount must be a string")
    if re.fullmatch(r"[0-9]+\.[0-9]{2}", amount) is None:
        raise ValueError("amount must match 'digits.digits-two' format")

    dollars, cents = amount.split(".")
    total_cents = int(dollars) * 100 + int(cents)

    allocated = allocate(total_cents, ratios)
    return [f"{part // 100}.{part % 100:02d}" for part in allocated]
