from datetime import date, datetime, timedelta


def _validate_date(d, name):
    if not isinstance(d, date) or isinstance(d, datetime):
        raise TypeError(f"{name} must be a datetime.date (not datetime.datetime)")


def _is_business_day(d, holiday_set):
    return d.weekday() < 5 and d not in holiday_set


def _count_weekdays(start, end):
    total = (end - start).days
    weeks, rem = divmod(total, 7)
    count = weeks * 5
    start_wd = start.weekday()
    for i in range(rem):
        if (start_wd + i) % 7 < 5:
            count += 1
    return count


def _business_days_count(start, end, holiday_set):
    count = _count_weekdays(start, end)
    for h in holiday_set:
        if start <= h < end and h.weekday() < 5:
            count -= 1
    return count


def business_days(start, end, holidays=()):
    _validate_date(start, "start")
    _validate_date(end, "end")
    holiday_set = set(holidays)
    if end < start:
        return -_business_days_count(end, start, holiday_set)
    return _business_days_count(start, end, holiday_set)


def add_business_days(start, n, holidays=()):
    _validate_date(start, "start")
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    holiday_set = set(holidays)
    if n == 0:
        return start
    step = 1 if n > 0 else -1
    delta = timedelta(days=step)
    current = start
    remaining = n
    while remaining != 0:
        current += delta
        if _is_business_day(current, holiday_set):
            remaining -= step
    return current
