class TextBuffer:
    def __init__(self, text=''):
        self._text = text
        self._history = []
        self._pointer = 0
        self._merge_insert = False
        self._merge_end = 0

    @property
    def text(self):
        return self._text

    def _clear_redo(self):
        if self._pointer < len(self._history):
            del self._history[self._pointer:]

    def insert(self, pos, s):
        if pos < 0 or pos > len(self._text):
            raise IndexError('insert position out of range')
        if not s:
            return
        self._clear_redo()
        if self._merge_insert and pos == self._merge_end:
            kind, start, old = self._history[-1]
            self._history[-1] = (kind, start, old + s)
            self._merge_end += len(s)
        else:
            self._history.append(('i', pos, s))
            self._pointer += 1
            self._merge_insert = True
            self._merge_end = pos + len(s)
        self._text = self._text[:pos] + s + self._text[pos:]

    def delete(self, pos, length):
        if pos < 0 or length < 0 or pos + length > len(self._text):
            raise IndexError('delete range out of range')
        if length == 0:
            return
        removed = self._text[pos:pos + length]
        self._clear_redo()
        self._history.append(('d', pos, removed))
        self._pointer += 1
        self._text = self._text[:pos] + self._text[pos + length:]
        self._merge_insert = False

    def undo(self):
        if self._pointer == 0:
            self._merge_insert = False
            return False
        self._pointer -= 1
        kind, pos, txt = self._history[self._pointer]
        if kind == 'i':
            self._text = self._text[:pos] + self._text[pos + len(txt):]
        else:
            self._text = self._text[:pos] + txt + self._text[pos:]
        self._merge_insert = False
        return True

    def redo(self):
        if self._pointer == len(self._history):
            self._merge_insert = False
            return False
        kind, pos, txt = self._history[self._pointer]
        if kind == 'i':
            self._text = self._text[:pos] + txt + self._text[pos:]
        else:
            self._text = self._text[:pos] + self._text[pos + len(txt):]
        self._pointer += 1
        self._merge_insert = False
        return True

    def history_size(self):
        return self._pointer
