import re


def _class_to_regex(contents, negated):
    parts = []
    prev_char = None
    i = 0
    n = len(contents)
    while i < n:
        ch = contents[i]
        if ch == '-' and i != 0 and i != n - 1 and prev_char is not None:
            nxt = contents[i + 1]
            if prev_char <= nxt and parts and parts[-1][0] == 'char' and parts[-1][1] == prev_char:
                parts.pop()
                parts.append(('range', prev_char, nxt))
                prev_char = nxt
                i += 2
                continue
        parts.append(('char', ch))
        prev_char = ch
        i += 1

    if not negated:
        filtered = []
        for part in parts:
            if part[0] == 'char':
                if part[1] != '/':
                    filtered.append(part)
            else:
                a, b = part[1], part[2]
                if a <= '/' <= b:
                    if a < '/':
                        filtered.append(('range', a, chr(ord('/') - 1)))
                    if b > '/':
                        filtered.append(('range', chr(ord('/') + 1), b))
                else:
                    filtered.append(part)
        parts = filtered
        if not parts:
            return '(?!)'

    if negated:
        pieces = ['[^']
        for part in parts:
            if part[0] == 'char':
                pieces.append(re.escape(part[1]))
            else:
                pieces.append(re.escape(part[1]) + '-' + re.escape(part[2]))
        pieces.append('/]')
        return ''.join(pieces)
    else:
        pieces = ['[']
        for part in parts:
            if part[0] == 'char':
                pieces.append(re.escape(part[1]))
            else:
                pieces.append(re.escape(part[1]) + '-' + re.escape(part[2]))
        pieces.append(']')
        return ''.join(pieces)


def glob_to_regex(pattern):
    i = 0
    n = len(pattern)
    out = []
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 < n:
                out.append(re.escape(pattern[i + 1]))
                i += 2
            else:
                out.append(re.escape('\\'))
                i += 1
        elif c == '?':
            out.append('[^/]')
            i += 1
        elif c == '*':
            j = i
            while j < n and pattern[j] == '*':
                j += 1
            run_len = j - i
            prev_is_sep = (i == 0) or (pattern[i - 1] == '/')
            next_is_sep_or_end = (j == n) or (pattern[j] == '/')
            if run_len == 2 and prev_is_sep and next_is_sep_or_end:
                if j < n and pattern[j] == '/':
                    out.append('(?:[^/]+/)*')
                    i = j + 1
                else:
                    out.append(r'[\s\S]*')
                    i = j
            else:
                out.append('[^/]*')
                i = j
        elif c == '[':
            start = i
            i += 1
            negated = False
            if i < n and pattern[i] == '!':
                negated = True
                i += 1
            literal_first = False
            if i < n and pattern[i] == ']':
                literal_first = True
                i += 1
            k = i
            while k < n:
                if pattern[k] == '\\':
                    k += 2
                elif pattern[k] == ']':
                    break
                else:
                    k += 1
            if k >= n:
                out.append(re.escape('['))
                i = start + 1
                continue
            contents = []
            if literal_first:
                contents.append(']')
            p = i
            while p < k:
                if pattern[p] == '\\' and p + 1 < k:
                    contents.append(pattern[p + 1])
                    p += 2
                else:
                    contents.append(pattern[p])
                    p += 1
            out.append(_class_to_regex(contents, negated))
            i = k + 1
        else:
            out.append(re.escape(c))
            i += 1
    return ''.join(out)


def glob_match(pattern, path):
    return re.fullmatch(glob_to_regex(pattern), path) is not None
