_DIGITS = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
_CHECK = _DIGITS + "*~$=U"
_DIGIT_MAP = {c: i for i, c in enumerate(_DIGITS)}
_CHECK_MAP = {c: i for i, c in enumerate(_CHECK)}


def encode_id(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        digits = "0"
    else:
        chars = []
        value = n
        while value:
            chars.append(_DIGITS[value % 32])
            value //= 32
        digits = "".join(reversed(chars))
    return digits + _CHECK[n % 37]


def decode_id(s):
    cleaned = (
        s.replace("-", "")
        .upper()
        .replace("I", "1")
        .replace("L", "1")
        .replace("O", "0")
    )
    if len(cleaned) < 2:
        raise ValueError("too short")
    digit_part = cleaned[:-1]
    check_char = cleaned[-1]
    for ch in digit_part:
        if ch not in _DIGIT_MAP:
            raise ValueError("invalid digit")
    if check_char not in _CHECK_MAP:
        raise ValueError("invalid check symbol")
    value = 0
    for ch in digit_part:
        value = value * 32 + _DIGIT_MAP[ch]
    if value % 37 != _CHECK_MAP[check_char]:
        raise ValueError("checksum mismatch")
    return value
