import re

_VERSION_RE = re.compile(
    r"""
    [vV]?
    (?P<major>0|[1-9][0-9]*)
    \.
    (?P<minor>0|[1-9][0-9]*)
    \.
    (?P<patch>0|[1-9][0-9]*)
    (?:-(?P<pre>[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?
    (?:\+(?P<build>[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?
    """,
    re.VERBOSE,
)


def parse_version(text):
    if not isinstance(text, str):
        raise ValueError("invalid version: input must be a string")
    match = _VERSION_RE.fullmatch(text)
    if not match:
        raise ValueError(f"invalid version: {text!r}")
    major = int(match.group("major"))
    minor = int(match.group("minor"))
    patch = int(match.group("patch"))
    pre_raw = match.group("pre")
    prerelease = ()
    if pre_raw is not None:
        parts = []
        for part in pre_raw.split("."):
            if part.isdigit():
                if len(part) > 1 and part[0] == "0":
                    raise ValueError(
                        f"invalid version: numeric prerelease identifier has leading zero: {part!r}"
                    )
                parts.append(int(part))
            else:
                parts.append(part)
        prerelease = tuple(parts)
    build = match.group("build")
    return (major, minor, patch, prerelease, build)


def compare_versions(a, b):
    av = parse_version(a)
    bv = parse_version(b)
    for idx in (0, 1, 2):
        if av[idx] < bv[idx]:
            return -1
        if av[idx] > bv[idx]:
            return 1
    pre_a = av[3]
    pre_b = bv[3]
    if not pre_a and not pre_b:
        return 0
    if not pre_a:
        return 1
    if not pre_b:
        return -1
    for ia, ib in zip(pre_a, pre_b):
        na = isinstance(ia, int)
        nb = isinstance(ib, int)
        if na and nb:
            if ia < ib:
                return -1
            if ia > ib:
                return 1
        elif na:
            return -1
        elif nb:
            return 1
        else:
            if ia < ib:
                return -1
            if ia > ib:
                return 1
    if len(pre_a) < len(pre_b):
        return -1
    if len(pre_a) > len(pre_b):
        return 1
    return 0


def sort_versions(versions):
    parsed = [(parse_version(v), v) for v in versions]

    def _pre_key(pre):
        return tuple((0, p) if isinstance(p, int) else (1, p) for p in pre)

    def _key(item):
        major, minor, patch, pre, build = item[0]
        return (major, minor, patch, 0 if pre else 1, _pre_key(pre))

    return [item[1] for item in sorted(parsed, key=_key)]
