def wrap_text(text, width):
    if not isinstance(width, int) or width < 2:
        raise ValueError("width must be an int >= 2")

    words = text.split()
    if not words:
        return []

    lines = []
    current = None

    for word in words:
        if len(word) > width:
            if current is not None:
                lines.append(current)
                current = None

            i = 0
            while len(word) - i > width:
                lines.append(word[i:i + width - 1] + '-')
                i += width - 1

            current = word[i:]
        else:
            if current is None:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current += ' ' + word
            else:
                lines.append(current)
                current = word

    if current is not None:
        lines.append(current)

    return lines
