def validate_stream(events):
    events = list(events)
    seen = set()
    for event in events:
        event_id = event[1]
        if event_id in seen:
            raise ValueError(f"duplicate id: {event_id!r}")
        seen.add(event_id)
    prev = None
    for event in events:
        key = (event[0], event[1])
        if prev is not None and key <= prev:
            raise ValueError(f"unsorted at {event!r}")
        prev = key
    return None


def diff_events(old, new):
    validate_stream(old)
    validate_stream(new)
    old = list(old)
    new = list(new)
    old_map = {event[1]: event for event in old}
    new_map = {event[1]: event for event in new}
    old_ids = set(old_map)
    new_ids = set(new_map)

    added = [event[1] for event in new if event[1] not in old_ids]
    removed = [event[1] for event in old if event[1] not in new_ids]
    moved = []
    changed = []

    for event in new:
        event_id = event[1]
        if event_id in old_ids:
            old_event = old_map[event_id]
            if event[0] != old_event[0]:
                moved.append(event_id)
            if event[2] != old_event[2]:
                changed.append(event_id)

    return {
        "added": added,
        "removed": removed,
        "moved": moved,
        "changed": changed,
    }


def merge_streams(a, b):
    validate_stream(a)
    validate_stream(b)
    a = list(a)
    b = list(b)
    merged = {event[1]: event for event in a}
    merged.update({event[1]: event for event in b})
    return sorted(merged.values(), key=lambda event: (event[0], event[1]))
