import copy


def _decode_token(token):
    out = []
    i = 0
    n = len(token)
    while i < n:
        ch = token[i]
        if ch == '~':
            if i + 1 >= n:
                raise ValueError("Invalid escape sequence")
            nxt = token[i + 1]
            if nxt == '0':
                out.append('~')
                i += 2
            elif nxt == '1':
                out.append('/')
                i += 2
            else:
                raise ValueError("Invalid escape sequence")
        else:
            out.append(ch)
            i += 1
    return ''.join(out)


def _split_pointer(pointer):
    if not isinstance(pointer, str):
        raise ValueError("Pointer must be a string")
    if pointer == '':
        return []
    if not pointer.startswith('/'):
        raise ValueError("Pointer must start with '/'")
    return [_decode_token(t) for t in pointer.split('/')[1:]]


def _parse_index(token, length):
    if token == '0':
        if length == 0:
            raise KeyError(token)
        return 0
    if not token or token[0] == '0' or not token.isdigit():
        raise KeyError(token)
    idx = int(token)
    if idx >= length:
        raise KeyError(token)
    return idx


def _parse_index_for_set(token, length):
    if token == '0':
        return 0
    if not token or token[0] == '0' or not token.isdigit():
        raise KeyError(token)
    idx = int(token)
    if idx > length:
        raise KeyError(token)
    return idx


def resolve(doc, pointer):
    tokens = _split_pointer(pointer)
    current = doc
    for token in tokens:
        if isinstance(current, dict):
            if token in current:
                current = current[token]
            else:
                raise KeyError(token)
        elif isinstance(current, list):
            current = current[_parse_index(token, len(current))]
        else:
            raise KeyError(token)
    return current


def set_value(doc, pointer, value):
    if pointer == '':
        return value
    tokens = _split_pointer(pointer)
    parent_tokens = tokens[:-1]
    last = tokens[-1]
    new_doc = copy.deepcopy(doc)
    parent = new_doc
    for token in parent_tokens:
        if isinstance(parent, dict):
            if token in parent:
                parent = parent[token]
            else:
                raise KeyError(token)
        elif isinstance(parent, list):
            parent = parent[_parse_index(token, len(parent))]
        else:
            raise KeyError(token)
    if isinstance(parent, dict):
        parent[last] = value
    elif isinstance(parent, list):
        if last == '-':
            parent.append(value)
        else:
            idx = _parse_index_for_set(last, len(parent))
            if idx == len(parent):
                parent.append(value)
            else:
                parent[idx] = value
    else:
        raise KeyError(last)
    return new_doc


def escape_token(token):
    return token.replace('~', '~0').replace('/', '~1')
