def rle_encode(s: str) -> str:
    if not s:
        return ""
    parts = []
    n = len(s)
    i = 0
    while i < n:
        j = i
        ch = s[i]
        while j < n and s[j] == ch:
            j += 1
        run_len = j - i
        if ch == "~" or run_len >= 4:
            parts.append(f"~{ch}{run_len};")
        else:
            parts.append(ch * run_len)
        i = j
    return "".join(parts)


def rle_decode(s: str) -> str:
    if not s:
        return ""
    parts = []
    n = len(s)
    i = 0
    while i < n:
        if s[i] != "~":
            parts.append(s[i])
            i += 1
            continue

        if i + 1 >= n:
            raise ValueError("escape character at end of input")
        run_char = s[i + 1]

        j = i + 2
        if j >= n or not ("0" <= s[j] <= "9"):
            raise ValueError("missing length digits after escape")

        start = j
        while j < n and "0" <= s[j] <= "9":
            j += 1

        if j >= n or s[j] != ";":
            raise ValueError("missing terminating semicolon")

        length_str = s[start:j]
        if length_str[0] == "0":
            raise ValueError("length has leading zero")

        run_len = int(length_str)
        parts.append(run_char * run_len)
        i = j + 1

    return "".join(parts)
