import re

_VERSION_RE = re.compile(r'^\d+(?:\.\d+)*$')
_OP_RE = re.compile(r'^(==|!=|>=|<=|~=|>|<)\s*(.+)$')


def _parse_version(s):
    t = s.strip()
    if not _VERSION_RE.match(t):
        raise ValueError(f"invalid version: {s!r}")
    return tuple(int(p) for p in t.split('.'))


def _compare(a, b):
    n = max(len(a), len(b))
    for i in range(n):
        av = a[i] if i < len(a) else 0
        bv = b[i] if i < len(b) else 0
        if av < bv:
            return -1
        if av > bv:
            return 1
    return 0


def _parse_spec(spec):
    s = spec.strip()
    if not s:
        return []
    clauses = []
    for raw in s.split(','):
        clause = raw.strip()
        if not clause:
            raise ValueError(f"empty clause in spec: {spec!r}")
        m = _OP_RE.match(clause)
        if not m:
            raise ValueError(f"invalid clause: {clause!r}")
        op, ver = m.group(1), _parse_version(m.group(2))
        if op == '~=':
            if len(ver) < 2:
                raise ValueError(f"~= requires multi-component version: {clause!r}")
            upper = list(ver[:-1])
            upper[-1] += 1
            upper = tuple(upper)
            clauses.append(('~=', ver, upper))
        else:
            clauses.append((op, ver))
    return clauses


def _eval_clause(vtuple, clause):
    op = clause[0]
    if op == '==':
        return _compare(vtuple, clause[1]) == 0
    if op == '!=':
        return _compare(vtuple, clause[1]) != 0
    if op == '>=':
        return _compare(vtuple, clause[1]) >= 0
    if op == '<=':
        return _compare(vtuple, clause[1]) <= 0
    if op == '>':
        return _compare(vtuple, clause[1]) > 0
    if op == '<':
        return _compare(vtuple, clause[1]) < 0
    if op == '~=':
        return _compare(vtuple, clause[1]) >= 0 and _compare(vtuple, clause[2]) < 0
    raise ValueError(f"unknown operator: {op!r}")


def satisfies(version, spec):
    vtuple = _parse_version(version)
    for clause in _parse_spec(spec):
        if not _eval_clause(vtuple, clause):
            return False
    return True


def max_satisfying(versions, spec):
    parsed = []
    for v in versions:
        parsed.append((v, _parse_version(v)))
    clauses = _parse_spec(spec)
    best_str = None
    best_tuple = None
    for orig, vtuple in parsed:
        if all(_eval_clause(vtuple, c) for c in clauses):
            if best_tuple is None or _compare(vtuple, best_tuple) > 0:
                best_str = orig
                best_tuple = vtuple
    return best_str
